class ClapAudioIntermediate(Module):
    def __init__(self, dim: int, mlp_ratio: float) -> None:
        self.dense = Linear(dim, int(mlp_ratio * dim))

    def forward(self, hidden: Tensor) -> Tensor:
        return F.gelu(self.dense(hidden))


